package com.mamtrex.hospital.document;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/documents") public class DocumentRecordController { private final DocumentRecordRepository repo; private final AuditService audit; public DocumentRecordController(DocumentRecordRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String ownerType, @jakarta.validation.constraints.NotBlank String ownerId, @jakarta.validation.constraints.NotBlank String fileName, @jakarta.validation.constraints.NotBlank String contentType, @jakarta.validation.constraints.NotBlank String storageKey){} @PostMapping public DocumentRecord create(@Valid @RequestBody Request r){var e=repo.save(new DocumentRecord(r.ownerType(), r.ownerId(), r.fileName(), r.contentType(), r.storageKey()));audit.record("CREATE","DocumentRecord",e.getId().toString(),"created");return e;} @GetMapping public List<DocumentRecord> list(){return repo.findAll();} @GetMapping("/{id}") public DocumentRecord get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("DocumentRecord not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("DocumentRecord not found: "+id);repo.deleteById(id);audit.record("DELETE","DocumentRecord",id.toString(),"deleted");} }
